using System;using System.Data.SqlClient;using System.Windows.Forms;using AshkanJobCenter.Core;using AshkanJobCenter.Data;
namespace AshkanJobCenter.UI{public class EmailTemplatePage:UserControl{DataGridView grid;TextBox name,subject,body;CheckBox active;public EmailTemplatePage(){if(!AppSession.Can("Users.Manage")){Controls.Add(Ui.Label(L.Fa?"دسترسی ندارید":"Access denied",16,true));return;}Dock=DockStyle.Fill;var edit=Ui.Card();edit.Dock=DockStyle.Top;edit.Height=190;name=Ui.Text();name.Width=180;subject=Ui.Text();subject.Width=300;body=new TextBox{Multiline=true,Width=500,Height=80,ScrollBars=ScrollBars.Vertical};active=new CheckBox{Text=L.Fa?"فعال":"Active",Checked=true,AutoSize=true};var save=Ui.Button(L.Fa?"ذخیره قالب":"Save template");save.Click+=(s,e)=>Save();var flow=new FlowLayoutPanel{Dock=DockStyle.Fill,AutoScroll=true};flow.Controls.AddRange(new Control[]{Ui.Label(L.Fa?"نام":"Name"),name,Ui.Label(L.Fa?"موضوع":"Subject"),subject,active,body,save});edit.Controls.Add(flow);grid=Ui.Grid();Controls.Add(grid);Controls.Add(edit);LoadRows();}void Save(){if(string.IsNullOrWhiteSpace(name.Text))return;Database.Exec("INSERT EmailTemplates(Name,Subject,Body,IsActive) VALUES(@n,@s,@b,@a)",new SqlParameter("@n",name.Text),new SqlParameter("@s",subject.Text),new SqlParameter("@b",body.Text),new SqlParameter("@a",active.Checked));Database.Audit("Create","EmailTemplate",name.Text);name.Clear();subject.Clear();body.Clear();LoadRows();}void LoadRows(){grid.DataSource=Database.Query("SELECT Id,Name,Subject,IsActive,CreatedAt FROM EmailTemplates ORDER BY Id DESC");}}}
